const holWin = v => { const m = /(\d{1,2}):(\d{2})\s*([AP]M)\s*[-–]\s*(\d{1,2}):(\d{2})\s*([AP]M)/i.exec(v || ''); if (!m) return null;
  const t = (h, mm, ap) => ((+h) % 12 + (/p/i.test(ap) ? 12 : 0)) * 60 + (+mm); return [t(m[1], m[2], m[3]), t(m[4], m[5], m[6])]; };
